package com.benabdallah.csvpipeline.api;
import com.benabdallah.csvpipeline.adapter.postgres.*; import com.benabdallah.csvpipeline.adapter.s3.*; import com.benabdallah.csvpipeline.application.port.out.*; import com.benabdallah.csvpipeline.application.service.*; import java.time.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.transaction.PlatformTransactionManager; import org.springframework.transaction.support.TransactionTemplate; import software.amazon.awssdk.regions.Region; import software.amazon.awssdk.services.s3.*; import software.amazon.awssdk.services.s3.presigner.S3Presigner;
@Configuration public class PipelineConfiguration {
 @Bean JdbcUploadAdapter jdbcUploadAdapter(JdbcClient jdbc){return new JdbcUploadAdapter(jdbc);} @Bean TransactionRunner transactionRunner(PlatformTransactionManager tm){return new SpringTransactionRunner(new TransactionTemplate(tm));}
 @Bean S3Client s3Client(@Value("${pipeline.s3.region}")String region){return S3Client.builder().region(Region.of(region)).build();} @Bean S3Presigner s3Presigner(@Value("${pipeline.s3.region}")String region){return S3Presigner.builder().region(Region.of(region)).build();}
 @Bean ObjectStoragePort objectStorage(S3Client c,S3Presigner p,@Value("${pipeline.s3.bucket}")String bucket,@Value("${pipeline.s3.presign-ttl:PT15M}")Duration ttl){return new S3ObjectStorageAdapter(c,p,new S3Properties(bucket,ttl));}
 @Bean CreateUploadService createUploadService(JdbcUploadAdapter db,ObjectStoragePort s3,TransactionRunner tx){return new CreateUploadService(db,db,s3,tx);} @Bean CompleteUploadService completeUploadService(JdbcUploadAdapter db,ObjectStoragePort s3,TransactionRunner tx){return new CompleteUploadService(db,s3,db,tx,Clock.systemUTC());}
}
